    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Nem nướng cuốn rau thơm, chấm tương béo, ngon quá (so tasty) là đúng bài."
    },
    {
      "poi_id": "p20",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chợ đêm nhộn nhịp, đi lòng vòng ngửi mùi bắp nướng và sữa đậu nành nóng."
    }
  ]
}
