```json
{
  "stops": [
    {
      "poi_id": "p90",
      "kind": "activity",
      "must_do_id": null,
      "note": "Thác đổ trắng xóa giữa rừng thông, lối đi bộ mát rượi và tiếng nước át cả suy nghĩ."
    },
    {
      "poi_id": "p16",
      "kind": "activity",
      "must_do_id": null,
      "note": "Không gian thiền tĩnh lặng, nhìn xuống hồ từ hiên chùa là thấy lòng nhẹ tênh."
    },
    {
      "poi_id": "p173",
      "kind": "activity",
      "must_do_id": null,
      "note": "Mặt hồ rộng, thông reo ven bờ, cứ thong thả dạo một vòng cho đã mắt."
    },
    {
      "poi_id": "p80",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tô bánh canh cua nóng hổi, ngọt từ thịt cua tươi, ăn xong còn muốn húp cạn nước."
    },
    {
      "poi_id": "p215",
      "kind": "activity",
      "must_do_id": null,
      "note": "Vườn hoa và tiểu cảnh xinh xắn, chỗ nào cũng thành góc chụp hình được."
    },
    {
      "poi_id": "p284",
      "kind": "meal",
      "must_do_id": null,
      "note": "Gà đồi nướng muối ớt cay thơm, ngồi lai rai nghe chuyện phố núi về đêm."
    }
  ]
}
```

```json
