    },
    {
      "poi_id": "p129",
      "kind": "activity",
      "must_do_id": null,
      "note": "Thung lũng tình yêu đi dạo thật chậm, chụp vài kiểu ảnh giữa vườn hoa và hồ nước lặng."
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "Nhà thờ Con Gà cổ kính, đứng từ xa đã thấy tháp chuông vươn lên trời, vào trong nghe gió hát qua khe cửa."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Góc nhỏ trong hẻm, ngồi xuống là thấy ấm cúng, món ăn bày ra như một bức tranh nhỏ xinh."
    },
    {
      "poi_id": "p52",
      "kind": "activity",
      "must_do_id": null,
      "note": "Lululola về đêm lên đèn, nhạc nhẹ, cà phê thơm, ngồi một góc ngắm phố núi chậm rãi trôi."
    }
  ]
}
